<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
admin_required();

$connection = db();
$notice = null;
$error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $username = trim((string) ($_POST['username'] ?? ''));
    $password = (string) ($_POST['password'] ?? '');
    $confirm = (string) ($_POST['confirm_password'] ?? '');
    if (!preg_match('/^[A-Za-z0-9._-]{3,60}$/', $username)) $error = 'Use 3-60 letters, numbers, dots, hyphens, or underscores for the username.';
    elseif (strlen($password) < 10) $error = 'The password must have at least 10 characters.';
    elseif ($password !== $confirm) $error = 'The password confirmation does not match.';
    else {
        try {
            $hash = password_hash($password, PASSWORD_DEFAULT);
            $statement = $connection->prepare('INSERT INTO administrators (username, password_hash) VALUES (?, ?)');
            $statement->bind_param('ss', $username, $hash);
            $statement->execute();
            $notice = 'Staff account created. Share the username and password privately.';
        } catch (mysqli_sql_exception $exception) { $error = (int) $exception->getCode() === 1062 ? 'That username is already in use.' : 'The staff account could not be created.'; }
    }
}
$users = $connection->query('SELECT id, username, created_at FROM administrators ORDER BY created_at ASC')->fetch_all(MYSQLI_ASSOC);
echo <<<'STYLE'
<style>
body:before{content:"";position:fixed;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(11,155,215,.045) 1px,transparent 1px),linear-gradient(rgba(11,155,215,.045) 1px,transparent 1px);background-size:34px 34px;mask-image:linear-gradient(to bottom,black,transparent 70%)}.page{position:relative}.back{display:inline-flex;align-items:center;gap:8px;padding:10px 14px;border:1px solid #dce9df;border-radius:999px;background:rgba(255,255,255,.78);box-shadow:0 8px 22px rgba(16,35,28,.05)}.head{position:relative;padding:30px 34px;margin:24px 0 26px;border:1px solid #dbe8df;border-radius:20px;background:linear-gradient(110deg,#fff 0%,#fbfefb 65%,#e4f5f7 100%);box-shadow:0 16px 38px rgba(16,35,28,.08);overflow:hidden}.head:after{content:"";position:absolute;right:-72px;bottom:-110px;width:215px;height:215px;border:26px solid rgba(11,155,215,.13);border-radius:50%}.head:before{content:"";position:absolute;right:61px;top:25px;width:74px;height:74px;border-radius:50%;background:#0d251e url(../assets/images/sammy-tech-logo.jpeg) center/50px no-repeat;box-shadow:0 0 0 10px #e7f5f6}.head>*{position:relative;z-index:1}.head h1{font-size:52px}.head h1:after{content:"";display:block;width:70px;height:5px;margin-top:16px;border-radius:99px;background:linear-gradient(90deg,var(--lime),#1eb9e5)}.grid{gap:24px}.panel{position:relative;overflow:hidden;border:0;box-shadow:0 24px 48px rgba(16,35,28,.09)}.panel:first-child{border-top:6px solid var(--lime);background:linear-gradient(145deg,#fff,#fbfefb)}.panel:nth-child(2){border-top:6px solid #1ba8d0}.panel h2{font-size:25px}.panel:first-child h2:before{content:"01";display:inline-grid;place-items:center;width:27px;height:27px;margin-right:10px;border-radius:50%;background:var(--lime);font:500 10px 'DM Mono';vertical-align:3px}.panel:nth-child(2) h2:before{content:"02";display:inline-grid;place-items:center;width:27px;height:27px;margin-right:10px;border-radius:50%;background:#e3f5f8;color:#167b9d;font:500 10px 'DM Mono';vertical-align:3px}.form input{transition:border .18s ease,box-shadow .18s ease}.form input:hover{border-color:#7ba98e}.create{box-shadow:0 10px 20px rgba(16,35,28,.18);transition:transform .18s ease,box-shadow .18s ease}.create:hover{transform:translateY(-3px);box-shadow:0 15px 27px rgba(16,35,28,.25)}.security{border-radius:11px}.user{transition:transform .18s ease,box-shadow .18s ease}.user:hover{transform:translateY(-3px);box-shadow:0 12px 24px rgba(16,35,28,.08)}.avatar i{box-shadow:0 0 0 5px #f3f8e4}.role{background:#e5f5f7}@media(max-width:760px){.head{padding:25px 22px}.head:before{right:-20px;top:27px;opacity:.38}.head h1{font-size:40px}}@media(max-width:500px){.head h1{font-size:35px}.head{padding:23px 18px}}
</style>
STYLE;
?>
