</style></head><body><main class="page"><a class="back" href="index.php">&larr; Return to dashboard</a><header class="head"><p class="eyebrow">STAFF ACCESS</p><h1>Staff users.</h1><p>Create secure sign-in accounts for trusted Sammy Tech staff.</p></header><section class="grid"><article class="panel"><h2>Add staff user</h2><p>Every user created here has full access to orders, products, reports, backups, and account settings.</p><?php if($notice): ?><div class="notice success"><?= e($notice) ?></div><?php endif; ?><?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>USERNAME<input name="username" required autocomplete="username" placeholder="e.g. sammy-staff"></label><label>TEMPORARY PASSWORD<input type="password" name="password" required autocomplete="new-password"></label><label>CONFIRM PASSWORD<input type="password" name="confirm_password" required autocomplete="new-password"></label><button class="create">Create staff account</button></form><aside class="security"><b>Security reminder:</b> share the temporary password privately and ask the staff member to change it through <em>My account</em> after their first sign-in.</aside></article><article class="panel"><h2>Current staff</h2><p><?= count($users) ?> administrator account<?= count($users) === 1 ? '' : 's' ?> can access the staff workspace.</p><div class="list"><?php foreach($users as $user): ?><div class="user"><div class="avatar"><i><?= e(strtoupper(substr($user['username'],0,1))) ?></i><span><b><?= e($user['username']) ?><?= (int)$user['id'] === (int)$_SESSION['admin_id'] ? ' (you)' : '' ?></b><small>Added <?= e(date('d M Y',strtotime($user['created_at']))) ?></small></span></div><span class="role">FULL ADMIN</span></div><?php endforeach; ?></div></article></section></main></body></html>
